mapper.delete:
DELETE FROM TB_CHPF001
 WHERE PRFL_ID = #{profileId}
   AND CP_ID   = #{cpId}
   AND CS_ID   = #{csId}

mapper.select:
SELECT PRFL_ID, CP_ID, CS_ID, EVSE_ID, STACK_LVL, PRPS, KIND, RCRNC_KIND,
       VALID_FROM, VALID_TO, RC_ID, CS_STATUS,
       MAX_OFFLINE_DURATION, INVALID_AFTER_OFFLINE, DYN_UPDATE_INTERVAL, DYN_UPDATE_TIME, PRICE_SCHED_SIGNATURE,
       REG_DT, REG_ID, UPD_DT, UPD_ID
  FROM TB_CHPF001

    AND CP_ID = #{cond.cpId}
    AND CS_ID = #{cond.csId}
    AND EVSE_ID = #{cond.evseId}
    AND PRPS = #{cond.purpose}

 ORDER BY PRFL_ID DESC
 LIMIT #{cond.pageItemSize} OFFSET #{cond.start}

SELECT COUNT(*)
  FROM TB_CHPF001

    AND CP_ID = #{cond.cpId}
    AND CS_ID = #{cond.csId}
    AND EVSE_ID = #{cond.evseId}
    AND PRPS = #{cond.purpose}

mapper.update:
UPDATE TB_CHLM001 SET ACTIVE_YN = 'N', UPD_DT = NOW()
 WHERE CP_ID = #{cpId} AND CS_ID = #{csId} AND ACTIVE_YN = 'Y'
   AND LIMIT_SOURCE = #{source}

   AND EVSE_ID = #{evseId}

